// Native question transcription from the owner's supplied examination PDFs.
// Question wording, figures and printed marks only. No worked answers appear here.
const p = (text) => ({ type: "paragraph", text });
const t = (caption, columns, rows) => ({ type: "table", caption, columns, rows });
const account = (caption, columns, rows, options = {}) => ({ ...t(caption, columns, rows), variant: "t-account", accountDivider: columns.length / 2, ...options });
const part = (label, text, marks) => ({ type: "part", label, text, marks });
const form = (answerId, caption, columns, rows, options = {}) => ({
  ...t(caption, columns, rows), answerSpace: true, answerId,
  ...(options.editableCells ? { readOnlyCells: rows.flatMap((row, r) => row.flatMap((cell, c) => cell === "" && !options.editableCells.includes(`${r}:${c}`) ? [`${r}:${c}`] : [])) } : {}),
  ...options,
});
const blankRows = (count, columns) => Array.from({ length: count }, () => Array(columns).fill(""));

